/* PsychLogic — Full-Length Mock 15 — Grand Final. Question bank. */
window.MOCK_QUESTIONS = [{"id": 1, "question": "Habitual, elaborate lying that is often fantastic and partly believed by the person, sometimes seen in factitious disorder, is called:", "options": ["Delusional misidentification", "Malingering", "Pseudologia fantastica", "Confabulation"], "correctAnswer": 2, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Pseudologia fantastica (Delbrück, 1891) is pathological lying with elaborate, plausible-sounding stories, often seen in Munchausen-type factitious disorder.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Delusional misidentification — Delusional misidentification involves fixed false beliefs about identity.</li><li>(B) Malingering — Malingering is faking for external gain.</li><li>(D) Confabulation — Confabulation is unintended filling of memory gaps.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Factitious disorder: falsifying illness without obvious external reward.</li><li>Munchausen syndrome is the severe, chronic form.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 2, "question": "<span class=\"pyq-badge\">PYQ</span>An exceptionally clear and vivid recollection of an important event is called:", "options": ["Engram", "Flashbulb memory", "Hindsight bias", "Equipotentiality hypothesis"], "correctAnswer": 1, "subject": "Cognition, learning & motivation", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Brown and Kulik (1977) coined ‘flashbulb memory’ for vivid memories of the circumstances in which one heard shocking news. Such memories feel accurate but can still be distorted.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Engram — An engram is a physical memory trace.</li><li>(C) Hindsight bias — Hindsight bias is the ‘I knew it all along’ effect.</li><li>(D) Equipotentiality hypothesis — Equipotentiality (Lashley) means cortical areas can take over each other’s functions.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Neisser showed flashbulb memories can be quite inaccurate.</li><li>Emotion and the amygdala strengthen memory.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 3, "question": "Ten-year-old Anil eats only a few foods of a certain texture and colour, gags on others, and has lost weight. He has no concern about his body shape or weight. The most likely DSM-5 diagnosis is:", "options": ["Avoidant/restrictive food intake disorder (ARFID)", "Anorexia nervosa", "Pica", "Rumination disorder"], "correctAnswer": 0, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> ARFID (new in DSM-5) is avoidance or restriction of food — due to sensory features, lack of interest or fear of choking — causing weight loss or nutritional problems, without body-image concerns.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Anorexia nervosa — Anorexia involves fear of weight gain and body-image disturbance.</li><li>(C) Pica — Pica is eating non-food substances.</li><li>(D) Rumination disorder — Rumination disorder is repeated regurgitation of food.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>ARFID replaced DSM-IV ‘feeding disorder of infancy or early childhood’.</li><li>It is common in autism.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 4, "question": "<span class=\"pyq-badge\">PYQ</span>Which neuroscientific technique provides the highest temporal resolution for studying neural activity?", "options": ["fMRI", "PET scan", "EEG", "CT scan"], "correctAnswer": 2, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> EEG records electrical activity directly, millisecond by millisecond, so its time resolution is excellent, though its spatial resolution is poor.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) fMRI — fMRI measures slower blood-flow changes (seconds).</li><li>(B) PET scan — PET is slower still.</li><li>(D) CT scan — CT shows structure, not activity.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>MEG also has excellent time resolution.</li><li>fMRI has better spatial resolution than EEG.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 5, "question": "Loss of the ability to feel pleasure in activities that were once enjoyable is called:", "options": ["Avolition", "Alexithymia", "Apathy", "Anhedonia"], "correctAnswer": 3, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Anhedonia is reduced capacity for pleasure. It is a core symptom of depression and a negative symptom of schizophrenia.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Avolition — Avolition is lack of motivation to start goal-directed activity.</li><li>(B) Alexithymia — Alexithymia is difficulty identifying and describing feelings.</li><li>(C) Apathy — Apathy is general lack of interest or concern.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Depression needs either depressed mood or loss of interest/pleasure.</li><li>The Snaith–Hamilton Pleasure Scale measures anhedonia.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 6, "question": "All of the following are elements of the FRAMES model of brief intervention for risky drinking, EXCEPT:", "options": ["Supervision", "Responsibility", "Feedback", "Self-efficacy"], "correctAnswer": 0, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> FRAMES = Feedback, Responsibility, Advice, Menu of options, Empathy and Self-efficacy (Miller and Sanchez). Supervision is not part of it.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Responsibility — Stressing the person’s responsibility is an element.</li><li>(C) Feedback — Feedback on personal risk is an element.</li><li>(D) Self-efficacy — Supporting self-efficacy is an element.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Brief interventions are widely used in primary care.</li><li>They are linked with motivational interviewing.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 7, "question": "Terror management theory proposes that reminders of death lead people to:", "options": ["Avoid all social groups", "Cling more strongly to their cultural worldviews and self-esteem", "Lose interest in cultural values", "Become more open to opposing views"], "correctAnswer": 1, "subject": "Social psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Greenberg, Solomon and Pyszczynski (based on Ernest Becker) showed that ‘mortality salience’ makes people defend their worldview and boost self-esteem to manage fear of death.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Avoid all social groups — People seek closer ties with their own group.</li><li>(C) Lose interest in cultural values — It strengthens, not weakens, cultural values.</li><li>(D) Become more open to opposing views — Mortality salience usually makes people less tolerant of opposing views.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Becker wrote The Denial of Death (1973).</li><li>Mortality salience can increase prejudice towards outgroups.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 8, "question": "Every year from November to February, Meena becomes depressed, sleeps much more and craves carbohydrates; she recovers fully each spring. Besides antidepressants, a well-supported treatment is:", "options": ["Exposure and response prevention", "Lithium only", "Psychoanalysis", "Bright light therapy"], "correctAnswer": 3, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> This is major depression with a seasonal pattern (seasonal affective disorder). Morning bright light therapy (about 10,000 lux) is an effective treatment.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Exposure and response prevention — ERP is for OCD.</li><li>(B) Lithium only — Lithium alone is not the specific treatment here.</li><li>(C) Psychoanalysis — Psychoanalysis is not first-line.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Norman Rosenthal described SAD in 1984.</li><li>Melatonin and circadian rhythms are thought to be involved.</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 9, "question": "Neurotransmitters are stored in synaptic vesicles and released into the synaptic cleft from the:", "options": ["Myelin sheath", "Dendrites", "Axon terminals", "Cell nucleus"], "correctAnswer": 2, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> When an action potential reaches the axon terminals, calcium enters and vesicles release neurotransmitter into the synaptic cleft.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Myelin sheath — Myelin insulates the axon.</li><li>(B) Dendrites — Dendrites mainly receive signals.</li><li>(D) Cell nucleus — The nucleus holds genetic material.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Reuptake and enzyme breakdown end the signal.</li><li>Botulinum toxin blocks acetylcholine release.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 10, "question": "In a 2 × 2 chi-square test, when expected frequencies are very small, a correction often applied is:", "options": ["Yates’ correction for continuity", "Welch’s correction", "Greenhouse–Geisser correction", "Bonferroni correction"], "correctAnswer": 0, "subject": "Research & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Yates (1934) suggested subtracting 0.5 from each |observed − expected| difference in 2 × 2 tables. With very small expected counts, Fisher’s exact test is preferred.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Welch’s correction — Welch’s correction is for unequal variances in t-tests.</li><li>(C) Greenhouse–Geisser correction — Greenhouse–Geisser corrects for sphericity in repeated-measures ANOVA.</li><li>(D) Bonferroni correction — Bonferroni adjusts alpha for multiple tests.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Chi-square assumes expected frequencies of at least 5 in most cells.</li><li>df for a 2 × 2 table = 1.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 11, "question": "After a night of heavy drinking, Raj cannot recall several hours of the evening, though he was awake and talking at the time. This alcohol-related memory gap is called a(n):", "options": ["Korsakoff psychosis", "Blackout (alcoholic palimpsest)", "Delirium tremens", "Alcoholic hallucinosis"], "correctAnswer": 1, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A blackout is anterograde amnesia for events during intoxication: alcohol blocks the formation of new long-term memories while the person is still awake and active.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Korsakoff psychosis — Korsakoff psychosis is a chronic amnestic syndrome from thiamine deficiency.</li><li>(C) Delirium tremens — Delirium tremens is a withdrawal state with confusion and autonomic overactivity.</li><li>(D) Alcoholic hallucinosis — Alcoholic hallucinosis is hallucinations with a clear sensorium.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Blackouts are an early warning sign of problem drinking (Jellinek).</li><li>Fragmentary blackouts are partial; en bloc blackouts are complete.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 12, "question": "Using self-help books to guide a client through therapeutic exercises at home is called:", "options": ["Hypnotherapy", "Psychodrama", "Play therapy", "Bibliotherapy"], "correctAnswer": 3, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Bibliotherapy uses structured reading (e.g. CBT self-help books) as a treatment or add-on, especially for mild depression and anxiety.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Hypnotherapy — Hypnotherapy uses hypnosis.</li><li>(B) Psychodrama — Psychodrama uses acting out scenes in a group.</li><li>(C) Play therapy — Play therapy uses play, mainly with children.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Guided self-help is a low-intensity step in stepped-care models.</li><li>‘Feeling Good’ (David Burns) is a well-known CBT self-help book.</li></ul>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 13, "question": "Aaron Beck’s ‘cognitive triad’ of depression refers to negative views of:", "options": ["Parents, peers and partners", "Past, present and future", "Oneself, the world and the future", "Thoughts, feelings and behaviour"], "correctAnswer": 2, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Beck (1967) proposed that depressed people hold negative views of the self (‘I am worthless’), the world (‘nothing goes right’) and the future (‘it will never get better’).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Parents, peers and partners — Relationships are not the triad.</li><li>(B) Past, present and future — Past, present and future is not Beck’s triad.</li><li>(D) Thoughts, feelings and behaviour — Thoughts, feelings and behaviour form the general CBT model.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Negative schemas give rise to automatic thoughts.</li><li>The Beck Hopelessness Scale measures negative views of the future.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 14, "question": "All of the following are primary index scores of the WISC-V, EXCEPT:", "options": ["Freedom from Distractibility", "Visual Spatial", "Processing Speed", "Fluid Reasoning"], "correctAnswer": 0, "subject": "Assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> WISC-V primary indices: Verbal Comprehension, Visual Spatial, Fluid Reasoning, Working Memory and Processing Speed. Freedom from Distractibility was a WISC-III factor.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Visual Spatial — Visual Spatial is a WISC-V index.</li><li>(C) Processing Speed — Processing Speed is a WISC-V index.</li><li>(D) Fluid Reasoning — Fluid Reasoning is a WISC-V index.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>WISC-V split the older perceptual reasoning index into visual spatial and fluid reasoning.</li><li>MISIC is an Indian adaptation of an older WISC.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 15, "question": "After a few minutes in a room, you no longer notice the smell of food cooking. This decline in response to a constant stimulus is:", "options": ["Habituation of a reflex in infancy", "Perceptual constancy", "Selective attention", "Sensory adaptation"], "correctAnswer": 3, "subject": "Cognition, learning & motivation", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Sensory adaptation is reduced sensitivity of receptors to an unchanging stimulus, letting us notice changes instead.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Habituation of a reflex in infancy — This is an everyday sensory change, not an infant reflex study.</li><li>(B) Perceptual constancy — Perceptual constancy keeps objects looking stable despite changing input.</li><li>(C) Selective attention — Selective attention is choosing what to focus on.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Adaptation is fastest for smell and touch.</li><li>Dark adaptation increases sensitivity in dim light.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 16, "question": "<span class=\"pyq-badge\">PYQ</span>Which intervention is generally most effective for students with dyscalculia (a math learning difficulty)?", "options": ["Speech therapy sessions.", "Multisensory math teaching approaches.", "Behavioral therapy for focus improvements.", "Physical coordination exercises."], "correctAnswer": 1, "subject": "Development", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Structured, explicit, multisensory teaching (using objects, visuals and movement) helps children with dyscalculia build number sense step by step.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Speech therapy sessions. — Speech therapy targets language and articulation.</li><li>(C) Behavioral therapy for focus improvements. — Attention training does not address core number difficulties.</li><li>(D) Physical coordination exercises. — Coordination exercises target motor skills.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Dyscalculia = specific learning disorder with impairment in mathematics.</li><li>Number sense is the core weakness.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 17, "question": "Huntington’s disease is inherited as an:", "options": ["Mitochondrial disorder", "Autosomal dominant disorder with an expanded CAG repeat on chromosome 4", "Autosomal recessive disorder on chromosome 21", "X-linked recessive disorder"], "correctAnswer": 1, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Huntington’s disease is autosomal dominant: each child of an affected parent has a 50% risk. The HTT gene has an expanded CAG repeat; longer repeats cause earlier onset.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Mitochondrial disorder — It is not mitochondrial.</li><li>(C) Autosomal recessive disorder on chromosome 21 — It is dominant, not recessive, and chromosome 21 is linked with Down syndrome and APP.</li><li>(D) X-linked recessive disorder — It is not X-linked.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Features: chorea, psychiatric symptoms and subcortical dementia.</li><li>Anticipation: onset gets earlier in successive generations.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 18, "question": "<span class=\"pyq-badge\">PYQ</span>Goal-Setting Theory emphasizes setting:", "options": ["Vague and broad", "Specific and challenging", "Easy and quick to achieve", "Unrelated to personal values"], "correctAnswer": 1, "subject": "Cognition, learning & motivation", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Edwin Locke and Gary Latham showed that specific, difficult (but achievable) goals, with commitment and feedback, lead to higher performance than ‘do your best’ goals.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Vague and broad — Vague goals lead to lower performance.</li><li>(C) Easy and quick to achieve — Easy goals produce less effort.</li><li>(D) Unrelated to personal values — Goals should be accepted and meaningful.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>SMART goals apply goal-setting theory.</li><li>Feedback is needed for goals to work.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 19, "question": "An elderly patient after surgery is quiet, drowsy and withdrawn, with fluctuating confusion and poor attention. Staff think she is simply ‘tired’. She most likely has:", "options": ["Hypoactive delirium", "Hyperactive delirium", "Catatonia", "Major depressive disorder"], "correctAnswer": 0, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Hypoactive delirium shows reduced activity, drowsiness and withdrawal with fluctuating inattention. It is often missed and carries a poor prognosis.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Hyperactive delirium — Hyperactive delirium shows agitation and restlessness.</li><li>(C) Catatonia — Catatonia has specific motor signs such as posturing or mutism.</li><li>(D) Major depressive disorder — Depression does not cause fluctuating attention and confusion.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The Confusion Assessment Method (CAM) screens for delirium.</li><li>Mixed delirium alternates between the two types.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 20, "question": "Robert Siegler’s ‘overlapping waves’ model of cognitive development proposes that:", "options": ["Children move through fixed stages one at a time", "Development depends only on maturation", "Strategies never change after age 7", "Children use several strategies at once, and the more efficient ones gradually become more frequent"], "correctAnswer": 3, "subject": "Development", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Siegler argued that children have several strategies available at the same time; better strategies gradually win out, like overlapping waves, rather than replacing each other in abrupt stages.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Children move through fixed stages one at a time — Fixed stages are Piaget’s view.</li><li>(B) Development depends only on maturation — Maturation alone is Gesell’s view.</li><li>(C) Strategies never change after age 7 — Strategy use keeps changing.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Siegler used the microgenetic method to study change closely.</li><li>It is an information-processing approach.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 21, "question": "Arrange E.M. Jellinek’s phases in the development of alcoholism in the correct order: I. Crucial phase II. Pre-alcoholic symptomatic phase III. Chronic phase IV. Prodromal phase", "options": ["IV, II, I, III", "II, I, IV, III", "II, IV, I, III", "II, IV, III, I"], "correctAnswer": 2, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Jellinek (1952): pre-alcoholic (drinking for relief) → prodromal (blackouts begin, secret drinking) → crucial (loss of control) → chronic (prolonged intoxication, morning drinking, physical decline).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The pre-alcoholic phase comes first and the chronic phase last; blackouts mark the prodromal phase before loss of control.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Jellinek also described types of alcoholism (alpha, beta, gamma, delta, epsilon).</li><li>His ‘disease concept’ (1960) shaped modern views of alcoholism.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 22, "question": "The ‘pancha kosha’ model of the self, describing five sheaths from the physical body to the blissful self, comes from the:", "options": ["Taittiriya Upanishad", "Yoga Sutras of Patanjali", "Charaka Samhita", "Arthashastra"], "correctAnswer": 0, "subject": "History, Indian psychology & ethics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The Taittiriya Upanishad describes five koshas: annamaya (food/body), pranamaya (vital breath), manomaya (mind), vijnanamaya (intellect) and anandamaya (bliss).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Yoga Sutras of Patanjali — Patanjali’s Yoga Sutras describe the eight limbs of yoga.</li><li>(C) Charaka Samhita — The Charaka Samhita is an Ayurvedic medical text.</li><li>(D) Arthashastra — The Arthashastra is a text on statecraft.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The kosha model is used in yoga-based therapies and Indian well-being research.</li><li>Patanjali described chitta vrittis (mental modifications).</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 23, "question": "A persistent feeling of a lump in the throat without any physical cause, once considered a classic sign of ‘hysteria’, is called:", "options": ["Torticollis", "Dysphagia due to stricture", "Aphonia", "Globus (globus hystericus)"], "correctAnswer": 3, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Globus is the sensation of a lump in the throat. It was historically linked with hysteria; today it is often linked with anxiety or reflux.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Torticollis — Torticollis is twisting of the neck.</li><li>(B) Dysphagia due to stricture — Dysphagia from stricture has a physical cause and real swallowing difficulty.</li><li>(C) Aphonia — Aphonia is loss of voice (can be functional).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>‘Hysteria’ comes from the Greek for womb (wandering-womb theory).</li><li>Functional neurological symptoms include paralysis, seizures and loss of sensation.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 24, "question": "Emotion-focused therapy, which helps clients become aware of, accept and transform emotions (e.g. using two-chair work), was developed mainly by:", "options": ["Aaron Beck", "Albert Ellis", "Leslie Greenberg", "Joseph Wolpe"], "correctAnswer": 2, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Leslie Greenberg (with Rice and Elliott) developed emotion-focused therapy, combining person-centred and Gestalt methods with emotion theory.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Aaron Beck — Beck developed cognitive therapy.</li><li>(B) Albert Ellis — Ellis developed REBT.</li><li>(D) Joseph Wolpe — Wolpe developed systematic desensitisation.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Emotion-focused couples therapy was developed by Sue Johnson and Greenberg.</li><li>EFT sees emotions as adaptive guides to needs.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 25, "question": "Depression ‘with atypical features’ in DSM-5 includes mood reactivity plus features such as:", "options": ["Onset only in adolescence", "Early-morning waking and severe weight loss", "Increased appetite or weight gain, oversleeping, ‘leaden paralysis’ and rejection sensitivity", "Psychotic features with nihilistic delusions"], "correctAnswer": 2, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Atypical features: mood brightens with positive events plus at least two of — weight gain or increased appetite, hypersomnia, leaden paralysis (heavy limbs) and long-standing rejection sensitivity.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Onset only in adolescence — Atypical depression is not limited to adolescence.</li><li>(B) Early-morning waking and severe weight loss — Early waking and weight loss are melancholic features.</li><li>(D) Psychotic features with nihilistic delusions — Psychotic features are a separate specifier.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Atypical depression was linked with better response to MAOIs.</li><li>It is more common in women and in bipolar depression.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 26, "question": "A test that looks, to the people taking it, as if it measures what it claims to measure has:", "options": ["Concurrent validity", "Predictive validity", "Construct validity", "Face validity"], "correctAnswer": 3, "subject": "Assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Face validity is about appearance only. It helps motivation and acceptance but is not real evidence of validity.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Concurrent validity — Concurrent validity is agreement with a criterion measured at the same time.</li><li>(B) Predictive validity — Predictive validity is about forecasting future criteria.</li><li>(C) Construct validity — Construct validity is evidence that the test measures the theoretical trait.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>High face validity can make faking easier.</li><li>Face validity is sometimes called ‘validity by assumption’.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 27, "question": "All of the following are features of depression ‘with melancholic features’ in DSM-5, EXCEPT:", "options": ["Early-morning awakening", "Mood reactivity (mood brightens with positive events)", "Excessive or inappropriate guilt", "Depression regularly worse in the morning"], "correctAnswer": 1, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Melancholic features include lack of mood reactivity, near-total loss of pleasure, morning worsening, early-morning waking, psychomotor change, weight loss and excessive guilt. Mood reactivity belongs to atypical features.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Early-morning awakening — Early-morning waking is a melancholic feature.</li><li>(C) Excessive or inappropriate guilt — Excessive guilt is a melancholic feature.</li><li>(D) Depression regularly worse in the morning — Morning worsening is a melancholic feature.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Melancholic depression often responds well to biological treatments.</li><li>Atypical features include mood reactivity, hypersomnia and weight gain.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}, {"id": 28, "question": "Match the therapy (List I) with its developer(s) (List II): List I: 1. Schema therapy   2. Mentalization-based treatment   3. Functional analytic psychotherapy   4. Interpersonal and social rhythm therapy List II: a. Ellen Frank   b. Robert Kohlenberg and Mavis Tsai   c. Anthony Bateman and Peter Fonagy   d. Jeffrey Young", "options": ["1-d, 2-c, 3-b, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-d, 2-b, 3-c, 4-a"], "correctAnswer": 0, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Schema therapy – Jeffrey Young (early maladaptive schemas, limited reparenting); MBT – Bateman and Fonagy (for borderline personality disorder); FAP – Kohlenberg and Tsai (shaping behaviour within the therapy relationship); IPSRT – Ellen Frank (for bipolar disorder, stabilising daily rhythms).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap Young with Bateman and Fonagy, or Kohlenberg and Tsai with Frank.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Evidence-based therapies for BPD: DBT, MBT, schema therapy and transference-focused psychotherapy.</li><li>FAP is one of the ‘third-wave’ behavioural therapies.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 29, "question": "<p class=\"stem-lead\">Read the Assertion (A) and Reason (R) and choose the correct option:</p><div class=\"ar-block\"><div class=\"ar-row\"><span class=\"ar-label\">Assertion (A)</span><span class=\"ar-text\">With large samples, tests based on the mean can often be used even if the population distribution is not normal.</span></div><div class=\"ar-row\"><span class=\"ar-label\">Reason (R)</span><span class=\"ar-text\">According to the central limit theorem, the sampling distribution of the mean approaches a normal distribution as sample size increases.</span></div></div>", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 0, "subject": "Research & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Both are true, and R explains A. Because sample means become approximately normal with large n (often n ≥ 30), parametric tests on means are robust to non-normal populations.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>B is wrong because R explains A.</li><li>C is wrong because R is true.</li><li>D is wrong because A is true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>SE of the mean = σ ÷ √n.</li><li>With small samples from skewed populations, non-parametric tests are safer.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 30, "question": "During motivational interviewing, a client says, ‘I really want to be there for my kids, and the drinking is getting in the way.’ In MI terms, this is:", "options": ["Discord", "Sustain talk", "Resistance", "Change talk"], "correctAnswer": 3, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Change talk is any client speech favouring change (desire, ability, reasons, need, commitment). MI aims to evoke and strengthen it.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Discord — Discord is friction in the client–counsellor relationship.</li><li>(B) Sustain talk — Sustain talk favours keeping things the same.</li><li>(C) Resistance — ‘Resistance’ is the older term now split into sustain talk and discord.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DARN-CAT: Desire, Ability, Reasons, Need — Commitment, Activation, Taking steps.</li><li>Miller and Rollnick developed MI (1983, 1991).</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 31, "question": "Prakash, 45, has long been suspicious that colleagues are exploiting him, reads hidden insults into innocent remarks, bears grudges and is reluctant to confide in anyone. He has no hallucinations or fixed delusions. The most likely diagnosis is:", "options": ["Delusional disorder, persecutory type", "Paranoid personality disorder", "Schizophrenia", "Avoidant personality disorder"], "correctAnswer": 1, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Paranoid personality disorder (Cluster A) is a pervasive, long-standing distrust and suspiciousness of others, without psychotic symptoms.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Delusional disorder, persecutory type — Delusional disorder needs a fixed false belief held with delusional conviction.</li><li>(C) Schizophrenia — Schizophrenia needs psychotic symptoms such as hallucinations or delusions.</li><li>(D) Avoidant personality disorder — Avoidant individuals fear rejection, not exploitation.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cluster A: paranoid, schizoid, schizotypal.</li><li>Projection is the main defence in paranoia.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 32, "question": "<p class=\"stem-lead\">Read the Assertion (A) and Reason (R) and choose the correct option:</p><div class=\"ar-block\"><div class=\"ar-row\"><span class=\"ar-label\">Assertion (A)</span><span class=\"ar-text\">Many antipsychotic drugs can raise prolactin levels, causing problems such as breast secretion and missed periods.</span></div><div class=\"ar-row\"><span class=\"ar-label\">Reason (R)</span><span class=\"ar-text\">They block D2 receptors in the tuberoinfundibular pathway, where dopamine normally inhibits prolactin release.</span></div></div>", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 0, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Both are true, and R explains A. Dopamine from the hypothalamus inhibits prolactin; blocking it lets prolactin rise.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>B is wrong because R explains A.</li><li>C is wrong because R is true.</li><li>D is wrong because A is true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Mesolimbic blockade reduces positive symptoms; nigrostriatal blockade causes extrapyramidal side effects.</li><li>Risperidone is especially known for raising prolactin.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 33, "question": "On a test that is too easy for a group, most people score near the maximum, so differences among high scorers cannot be seen. This is a:", "options": ["Floor effect", "Practice effect", "Ceiling effect", "Halo effect"], "correctAnswer": 2, "subject": "Assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A ceiling effect occurs when items are too easy, compressing scores at the top. A floor effect occurs when items are too hard.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Floor effect — A floor effect is clustering at the bottom.</li><li>(B) Practice effect — A practice effect is improvement from repeated testing.</li><li>(D) Halo effect — The halo effect is a rating bias.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Ceiling effects reduce variance and can hide treatment effects.</li><li>Adding harder items removes ceiling effects.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 34, "question": "Neurons that fire both when a monkey performs an action and when it watches another perform the same action were discovered in the premotor cortex by:", "options": ["Roger Sperry", "Giacomo Rizzolatti and colleagues", "Wilder Penfield", "Eric Kandel"], "correctAnswer": 1, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Rizzolatti’s team in Parma (1990s) found ‘mirror neurons’ in area F5 of the monkey premotor cortex. They are proposed to support imitation and understanding of actions.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Roger Sperry — Sperry studied split-brain patients.</li><li>(C) Wilder Penfield — Penfield mapped the cortex by stimulation during surgery.</li><li>(D) Eric Kandel — Kandel studied memory in Aplysia.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Claims linking mirror neurons to empathy and autism are debated.</li><li>Penfield’s maps gave the ‘homunculus’.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 35, "question": "Severely depressed Mr. Rao insists that he has ruined his family through his ‘sins’ and deserves to be punished, though there is no basis for this. This is a:", "options": ["Mood-incongruent delusion", "Overvalued idea", "Mood-congruent delusion of guilt", "Obsession"], "correctAnswer": 2, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In psychotic depression, delusions usually match the depressed mood — themes of guilt, sin, poverty, illness or nihilism. These are mood-congruent.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Mood-incongruent delusion — Mood-incongruent delusions (e.g. thought insertion) do not match the mood.</li><li>(B) Overvalued idea — An overvalued idea is held with less certainty.</li><li>(D) Obsession — Obsessions are recognised as one’s own unwanted thoughts and resisted.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Psychotic depression often needs antidepressant + antipsychotic or ECT.</li><li>Mood-congruent grandiose delusions occur in mania.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 36, "question": "In Milan systemic family therapy, the therapist asks one family member, ‘When your father gets angry, what does your mother do?’ This technique is:", "options": ["Genogram", "Paradoxical injunction", "Enactment", "Circular questioning"], "correctAnswer": 3, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Circular questions ask family members about relationships and differences between others, revealing patterns in the family system (Selvini Palazzoli and colleagues).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Genogram — A genogram is a family tree diagram (Bowen).</li><li>(B) Paradoxical injunction — Paradoxical injunctions prescribe the symptom.</li><li>(C) Enactment — Enactment is acting out a family pattern in session (structural therapy).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Milan team principles: hypothesising, circularity, neutrality.</li><li>Systemic therapy sees symptoms as serving a function in the family.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 37, "question": "In a one-way ANOVA, the mean square between groups is 30 and the mean square within groups is 6. The F ratio is:", "options": ["5", "24", "36", "0.2"], "correctAnswer": 0, "subject": "Research & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> F = MS between ÷ MS within = 30 ÷ 6 = 5.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 24 — 24 is the difference, not the ratio.</li><li>(C) 36 — 36 is the sum.</li><li>(D) 0.2 — 0.2 is the ratio upside down.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>A large F means group differences are big relative to error.</li><li>Significant F is followed by post-hoc tests.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 38, "question": "In McCrae and Costa’s five-factor theory, the Big Five traits are ‘basic tendencies’, whereas habits, attitudes, roles and relationships are called:", "options": ["Surface traits", "Source traits", "Characteristic adaptations", "Personal constructs"], "correctAnswer": 2, "subject": "Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Five-factor theory separates biologically based basic tendencies (traits) from characteristic adaptations, which develop as traits interact with the environment.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Surface traits — Surface traits are Cattell’s observable trait clusters.</li><li>(B) Source traits — Source traits are Cattell’s deep traits.</li><li>(D) Personal constructs — Personal constructs are Kelly’s concept.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>McCrae and Costa saw traits as largely stable after age 30.</li><li>The NEO-PI-3 measures 30 facets.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 39, "question": "A man is brought unconscious with pinpoint pupils and slow breathing after a heroin overdose. He wakes within minutes of an injection that blocks opioid receptors. The drug used is an opioid:", "options": ["Reuptake inhibitor", "Antagonist (naloxone)", "Agonist (morphine)", "Partial agonist (buprenorphine)"], "correctAnswer": 1, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> An antagonist binds the receptor without activating it and blocks the agonist. Naloxone rapidly reverses opioid overdose.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Reuptake inhibitor — Reuptake inhibitors act on monoamines such as serotonin.</li><li>(C) Agonist (morphine) — An agonist would worsen the overdose.</li><li>(D) Partial agonist (buprenorphine) — A partial agonist activates receptors partly; it is used for maintenance.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Naltrexone is a longer-acting antagonist used to prevent relapse.</li><li>Agonists mimic, antagonists block.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 40, "question": "<span class=\"pyq-badge\">PYQ</span>According to statistical approaches, what defines &#x27;abnormal&#x27; behavior?", "options": ["Deviation from typical behavioral patterns", "Experiencing intense anxiety", "Loss of contact with reality", "Withdrawal and depression"], "correctAnswer": 0, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The statistical approach defines abnormality as rarity — behaviour far from the average of the population (e.g. beyond 2 SD).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Experiencing intense anxiety — Intense anxiety reflects a distress criterion, not a statistical one.</li><li>(C) Loss of contact with reality — Loss of contact with reality is a clinical feature of psychosis.</li><li>(D) Withdrawal and depression — Withdrawal and depression are specific symptoms, not a definition.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Weakness: rare is not always bad (e.g. very high IQ).</li><li>Other criteria: distress, dysfunction, deviance from social norms, danger.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 41, "question": "Rats first learn that a tone predicts shock. Later a tone and a light are presented together before shock. When tested, the light alone produces almost no fear. Leon Kamin called this:", "options": ["Overshadowing", "Latent inhibition", "Higher-order conditioning", "Blocking"], "correctAnswer": 3, "subject": "Cognition, learning & motivation", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In blocking (Kamin, 1969), a stimulus already predicting the outcome prevents a new stimulus from being learned, because it adds no new information. This led to the Rescorla–Wagner model.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Overshadowing — Overshadowing is when the stronger of two new stimuli gains more control.</li><li>(B) Latent inhibition — Latent inhibition is slower learning about a stimulus previously presented alone.</li><li>(C) Higher-order conditioning — Higher-order conditioning uses a conditioned stimulus as the reinforcer.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Rescorla–Wagner (1972): learning depends on prediction error (surprise).</li><li>Blocking shows conditioning is about information, not just pairing.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 42, "question": "Acceptance-based behavioural therapy (ABBT) for generalised anxiety disorder, which combines mindfulness, acceptance and values-based action, was developed by:", "options": ["David Clark", "Adrian Wells", "Lizabeth Roemer and Susan Orsillo", "Thomas Borkovec alone"], "correctAnswer": 2, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Roemer and Orsillo developed ABBT, drawing on ACT, DBT and mindfulness, to reduce experiential avoidance in GAD.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) David Clark — David Clark developed cognitive models of panic and social anxiety.</li><li>(B) Adrian Wells — Wells developed metacognitive therapy.</li><li>(D) Thomas Borkovec alone — Borkovec developed the avoidance theory of worry and CBT for GAD.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Wells’s metacognitive model separates Type 1 and Type 2 (worry about worry) worries.</li><li>Intolerance of uncertainty (Dugas) is another GAD model.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 43, "question": "According to Freud, the id operates on the:", "options": ["Principle of constancy alone", "Pleasure principle", "Moral principle", "Reality principle"], "correctAnswer": 1, "subject": "Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The id seeks immediate gratification (pleasure principle). The ego follows the reality principle; the superego represents morality.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Principle of constancy alone — The constancy principle is a separate economic idea in Freud’s theory.</li><li>(C) Moral principle — The moral side belongs to the superego.</li><li>(D) Reality principle — The reality principle guides the ego.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Primary process thinking belongs to the id; secondary process to the ego.</li><li>The id is entirely unconscious.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 44, "question": "In DSM-5, delusional disorder requires delusions lasting at least:", "options": ["1 month", "1 week", "6 months", "2 years"], "correctAnswer": 0, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Delusional disorder needs one or more delusions for at least 1 month, with functioning not markedly impaired apart from the effects of the delusion.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 1 week — 1 week is too short.</li><li>(C) 6 months — 6 months is the schizophrenia duration.</li><li>(D) 2 years — 2 years is not required.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DSM-5 allows bizarre delusions in delusional disorder (with a specifier).</li><li>Types: erotomanic, grandiose, jealous, persecutory, somatic, mixed.</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 45, "question": "Clark Hull’s drive-reduction theory proposes that behaviour is motivated mainly by:", "options": ["The desire for self-actualisation", "The pull of external incentives alone", "The search for optimal arousal", "The need to reduce internal tension created by biological needs"], "correctAnswer": 3, "subject": "Cognition, learning & motivation", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Hull (1943) proposed that needs create drives (tension), and behaviours that reduce drives are reinforced. He expressed this as a formula: reaction potential = habit strength × drive.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) The desire for self-actualisation — Self-actualisation is Maslow’s idea.</li><li>(B) The pull of external incentives alone — Incentive theory stresses external pulls.</li><li>(C) The search for optimal arousal — Optimal arousal theory explains curiosity and thrill-seeking.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Drive theory cannot explain curiosity or seeking stimulation.</li><li>Homeostasis is the underlying idea.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 46, "question": "<span class=\"pyq-badge\">PYQ</span>A person who believes that he has control over events in his life, has what type of locus of control?", "options": ["External", "Internal", "Neutral", "Situational"], "correctAnswer": 1, "subject": "Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Julian Rotter (1966): people with an internal locus believe outcomes depend on their own actions; those with an external locus credit luck, fate or powerful others.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) External — External locus credits outside forces.</li><li>(C) Neutral — ‘Neutral’ is not one of Rotter’s types.</li><li>(D) Situational — ‘Situational’ is not one of Rotter’s types.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Rotter’s I-E Scale measures it.</li><li>Internal locus is linked with better health behaviour and achievement.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 47, "question": "In Exner’s Rorschach Comprehensive System, a very high ‘Lambda’ value (many pure form responses) mainly suggests:", "options": ["Strong emotional reactivity", "Rich imagination and creativity", "A narrow, simplifying, defensive style of dealing with complex stimuli", "Psychotic perceptual distortion"], "correctAnswer": 2, "subject": "Assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Lambda is the ratio of pure F (form-only) responses to other responses. A high Lambda suggests the person simplifies or avoids complexity, often defensively.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Strong emotional reactivity — Emotional reactivity is shown by colour responses.</li><li>(B) Rich imagination and creativity — Imagination is shown by movement responses.</li><li>(D) Psychotic perceptual distortion — Psychotic distortion is shown by poor form quality.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Exner’s system was published in 1974; R-PAS (2011) is a newer system.</li><li>Form quality (X+%) relates to reality testing.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 48, "question": "Robert Post’s ‘kindling’ hypothesis of mood disorders proposes that:", "options": ["Mood disorders are caused by seizures", "Recovery becomes faster with each episode", "Every episode needs the same severe stressor", "Early episodes need major stressors, but later episodes occur with little or no trigger"], "correctAnswer": 3, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Post (1992) borrowed the epilepsy concept of kindling: each episode sensitises the brain, so later episodes are triggered more easily and may start on their own.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Mood disorders are caused by seizures — It does not claim mood disorders are seizures.</li><li>(B) Recovery becomes faster with each episode — It predicts worsening, not faster recovery.</li><li>(C) Every episode needs the same severe stressor — The hypothesis says the need for stressors decreases.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>It supports early and maintenance treatment to prevent recurrence.</li><li>Anticonvulsants (valproate, carbamazepine) are used as mood stabilisers.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 49, "question": "All of the following are parts of the hindbrain, EXCEPT:", "options": ["Thalamus", "Cerebellum", "Medulla", "Pons"], "correctAnswer": 0, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The thalamus is part of the forebrain (diencephalon). The hindbrain consists of the medulla, pons and cerebellum.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Cerebellum — The cerebellum controls coordination and balance.</li><li>(C) Medulla — The medulla controls breathing and heart rate.</li><li>(D) Pons — The pons relays signals and is involved in sleep.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Midbrain: tectum (colliculi), tegmentum, substantia nigra.</li><li>Brainstem = medulla, pons and midbrain.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 50, "question": "Match the instrument (List I) with its developer (List II): List I: 1. Beck Depression Inventory   2. General Health Questionnaire   3. Child Behavior Checklist   4. Kaufman Assessment Battery for Children List II: a. Alan and Nadeen Kaufman   b. Thomas Achenbach   c. David Goldberg   d. Aaron Beck", "options": ["1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a", "1-d, 2-b, 3-c, 4-a"], "correctAnswer": 2, "subject": "Assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> BDI – Aaron Beck (1961; BDI-II with 21 items, 1996); GHQ – David Goldberg (1972), a community screening tool; CBCL – Thomas Achenbach, parent report of internalising and externalising problems; K-ABC – the Kaufmans (1983), based on Luria’s sequential and simultaneous processing.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap Beck with Goldberg, or Achenbach with the Kaufmans.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The HAM-D is clinician-rated; the BDI is self-report.</li><li>KABC-II offers both Luria and CHC scoring.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 51, "question": "Arrange Bowlby’s phases of attachment in the order in which they develop: I. Clear-cut attachment II. Pre-attachment III. Formation of a reciprocal relationship IV. Attachment in the making", "options": ["IV, II, I, III", "II, IV, I, III", "II, I, IV, III", "II, IV, III, I"], "correctAnswer": 1, "subject": "Development", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Pre-attachment (birth–6 weeks) → attachment in the making (6 weeks–6/8 months) → clear-cut attachment (6/8–18/24 months, with separation protest) → formation of a reciprocal relationship (from 18–24 months).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Pre-attachment comes first, and the reciprocal relationship comes last.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The internal working model forms during these phases.</li><li>Stranger anxiety appears in the clear-cut phase.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 52, "question": "<span class=\"pyq-badge\">PYQ</span>Which type of memory produces scripts of familiar routines?", "options": ["Generic memory", "Episodic memory", "Autobiographical memory", "Working memory"], "correctAnswer": 0, "subject": "Cognition, learning & motivation", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Generic (script) memory stores the general structure of repeated events — e.g. what usually happens at a restaurant — rather than one specific occasion.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Episodic memory — Episodic memory stores specific events.</li><li>(C) Autobiographical memory — Autobiographical memory is personal episodic memory about one’s life.</li><li>(D) Working memory — Working memory holds information briefly for use.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Schank and Abelson described scripts (1977).</li><li>Children form scripts very early (Nelson).</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 53, "question": "A test has a reliability coefficient of 0.90. According to classical test theory, the proportion of observed-score variance that is true-score variance is:", "options": ["90%", "81%", "10%", "95%"], "correctAnswer": 0, "subject": "Assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In classical test theory, the reliability coefficient itself equals the proportion of true-score variance in observed scores: 0.90 = 90% (and 10% is error).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 81% — 81% would be r squared — not used for a reliability coefficient.</li><li>(C) 10% — 10% is the error variance.</li><li>(D) 95% — 95% is not the right value.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>X = T + E (observed = true + error).</li><li>Correlation with true scores is √reliability (about 0.95 here).</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 54, "question": "‘Shame-attacking exercises’, in which a client deliberately does something mildly embarrassing in public to learn that disapproval is bearable, are a technique of:", "options": ["Psychoanalysis", "Person-centred therapy", "Interpersonal psychotherapy", "Rational emotive behaviour therapy (Albert Ellis)"], "correctAnswer": 3, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Ellis used shame-attacking exercises in REBT to challenge irrational beliefs such as ‘I must be approved of by everyone’.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Psychoanalysis — Psychoanalysis does not use behavioural homework.</li><li>(B) Person-centred therapy — Person-centred therapy does not use such tasks.</li><li>(C) Interpersonal psychotherapy — IPT focuses on interpersonal problem areas.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other REBT tools: disputing, rational-emotive imagery, homework.</li><li>Ellis described ‘musturbation’ — rigid ‘must’ demands.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 55, "question": "Carl Rogers described the ideal outcome of healthy development as the ‘fully functioning person’, who is:", "options": ["Driven mainly by unconscious instincts", "Strictly obedient to social rules", "Free of all anxiety and conflict", "Open to experience, living in the present, and trusting his own feelings"], "correctAnswer": 3, "subject": "Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Rogers’ fully functioning person is open to experience, lives existentially (in the moment), trusts his organism, feels free and is creative.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Driven mainly by unconscious instincts — Instinct-driven behaviour is Freud’s view.</li><li>(B) Strictly obedient to social rules — Strict conformity contradicts his ideas of authenticity.</li><li>(C) Free of all anxiety and conflict — Rogers did not describe a life without any conflict.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Rogers wrote On Becoming a Person (1961).</li><li>The actualising tendency drives growth.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 56, "question": "Adult neurogenesis — the birth of new neurons in adulthood — has been shown most clearly in humans and other mammals in the:", "options": ["Spinal cord", "Dentate gyrus of the hippocampus", "Primary visual cortex", "Cerebellar cortex"], "correctAnswer": 1, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> New neurons are generated in the dentate gyrus throughout life (Eriksson and colleagues, 1998). Exercise and enriched environments increase it; stress reduces it.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Spinal cord — The spinal cord does not.</li><li>(C) Primary visual cortex — The primary visual cortex does not.</li><li>(D) Cerebellar cortex — The cerebellar cortex does not show clear adult neurogenesis.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The subventricular zone is another neurogenic area in rodents.</li><li>Some antidepressant effects may involve neurogenesis.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 57, "question": "The CAGE questionnaire is a brief screening tool for:", "options": ["Dementia", "Depression", "Alcohol problems", "Anxiety"], "correctAnswer": 2, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> CAGE asks four questions: Have you felt you should Cut down? Have people Annoyed you by criticising your drinking? Have you felt Guilty? Have you needed an Eye-opener? Two or more ‘yes’ answers suggest a problem.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Dementia — Dementia is screened with tools such as the MMSE.</li><li>(B) Depression — Depression is screened with tools such as the PHQ-9.</li><li>(D) Anxiety — Anxiety is screened with tools such as the GAD-7.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The AUDIT (WHO) is a longer, 10-item alcohol screen.</li><li>CAGE was developed by John Ewing (1984).</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 58, "question": "A researcher records accident rates monthly for two years before and two years after a new helmet law, looking for a change at the point the law started. This design is a(n):", "options": ["Randomised controlled trial", "Interrupted time-series design", "Solomon four-group design", "Cross-sectional survey"], "correctAnswer": 1, "subject": "Research & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> An interrupted time-series design uses many measurements before and after an intervention to see whether the trend changes at the ‘interruption’. It is a strong quasi-experimental design.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Randomised controlled trial — An RCT needs random assignment to conditions.</li><li>(C) Solomon four-group design — The Solomon design uses random assignment and pre-tests.</li><li>(D) Cross-sectional survey — A cross-sectional survey measures once.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Many baseline points help rule out history and maturation.</li><li>Campbell and Stanley described it as a quasi-experiment.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 59, "question": "A 60-year-old develops a rapidly worsening dementia over a few months, with sudden muscle jerks (myoclonus) and an EEG showing periodic sharp-wave complexes. The most likely cause is:", "options": ["Vascular dementia", "Normal pressure hydrocephalus", "Alzheimer’s disease", "Creutzfeldt–Jakob disease"], "correctAnswer": 3, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Creutzfeldt–Jakob disease is a prion disease causing very fast dementia (death usually within a year), myoclonus and characteristic EEG changes.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Vascular dementia — Vascular dementia progresses in steps, with focal signs.</li><li>(B) Normal pressure hydrocephalus — Normal pressure hydrocephalus causes gait problems, incontinence and dementia.</li><li>(C) Alzheimer’s disease — Alzheimer’s disease progresses slowly over years.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Variant CJD was linked to ‘mad cow disease’.</li><li>Prions are misfolded proteins.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 60, "question": "When a teacher prepares an exam by making sure the questions fairly sample all the topics taught, she is mainly ensuring:", "options": ["Criterion validity", "Test–retest reliability", "Content validity", "Face validity only"], "correctAnswer": 2, "subject": "Assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Content validity is the extent to which items represent the whole domain to be measured, usually checked with a test blueprint and expert judgement.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Criterion validity — Criterion validity compares scores with an outside standard.</li><li>(B) Test–retest reliability — Test–retest reliability is consistency over time.</li><li>(D) Face validity only — Face validity is only about appearance.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>A table of specifications helps ensure content validity.</li><li>Lawshe’s content validity ratio uses expert ratings.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 61, "question": "Jane Loevinger’s theory of ego development, measured with the Washington University Sentence Completion Test, describes stages such as:", "options": ["Trust, autonomy, initiative and industry", "Preconventional, conventional and postconventional", "Oral, anal, phallic and genital", "Impulsive, conformist, conscientious and autonomous"], "correctAnswer": 3, "subject": "Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Loevinger described ego development from impulsive and self-protective, through conformist and conscientious, to autonomous and integrated stages.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Trust, autonomy, initiative and industry — These are Erikson’s first four stages.</li><li>(B) Preconventional, conventional and postconventional — These are Kohlberg’s moral levels.</li><li>(C) Oral, anal, phallic and genital — These are Freud’s psychosexual stages.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The WUSCT is a sentence-completion measure.</li><li>Loevinger’s work influenced adult development research.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 62, "question": "The body’s natural pain-relieving chemicals, sometimes called ‘feel-good’ neurotransmitters, are:", "options": ["Endorphins", "Histamine", "Glutamate", "Acetylcholine"], "correctAnswer": 0, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Endorphins are endogenous opioids that reduce pain and produce well-being, e.g. ‘runner’s high’.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Histamine — Histamine is involved in wakefulness and allergy.</li><li>(C) Glutamate — Glutamate is the main excitatory transmitter.</li><li>(D) Acetylcholine — Acetylcholine works in muscle movement and memory.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Morphine acts on the same opioid receptors.</li><li>Endorphins were discovered in the 1970s (Hughes, Kosterlitz; Pert and Snyder).</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 63, "question": "John Atkinson’s theory of achievement motivation predicts that people high in need for achievement prefer tasks of:", "options": ["Very high difficulty, where success is almost impossible", "Moderate difficulty, where success is uncertain", "Very low difficulty, where success is certain", "Any difficulty, equally"], "correctAnswer": 1, "subject": "Cognition, learning & motivation", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Atkinson (1957): tendency to achieve = motive × probability of success × incentive value. Since incentive rises as probability falls, motivation peaks at moderate difficulty (about 50% success).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Very high difficulty, where success is almost impossible — Very hard tasks give little chance of success.</li><li>(C) Very low difficulty, where success is certain — Easy tasks give little sense of accomplishment.</li><li>(D) Any difficulty, equally — The theory predicts a clear preference for moderate difficulty.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>People high in fear of failure prefer very easy or very hard tasks.</li><li>McClelland measured need for achievement with the TAT.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 64, "question": "Project MATCH, a large US trial (1990s), compared three treatments for alcohol problems. Its main finding was that:", "options": ["Matching patients to treatment by their characteristics greatly improved outcomes", "None of the treatments helped", "The three treatments (CBT, motivational enhancement and 12-step facilitation) gave broadly similar outcomes", "Only 12-step facilitation worked"], "correctAnswer": 2, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Project MATCH found broadly similar improvement across all three treatments and little support for the matching hypothesis.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Matching patients to treatment by their characteristics greatly improved outcomes — Matching added little.</li><li>(B) None of the treatments helped — Drinking fell substantially in all groups.</li><li>(D) Only 12-step facilitation worked — All three treatments helped.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Motivational enhancement therapy was only 4 sessions yet did as well.</li><li>This finding supports the role of common factors.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 65, "question": "Eleanor Rosch’s prototype theory proposes that we categorise objects by:", "options": ["Checking a strict list of necessary and sufficient features", "Their names only", "Comparing them with the most typical member of the category", "Remembering every example we have ever seen equally"], "correctAnswer": 2, "subject": "Cognition, learning & motivation", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Rosch (1970s) showed that categories have graded membership: a robin is a ‘better’ bird than a penguin because it is closer to the prototype.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Checking a strict list of necessary and sufficient features — Strict defining features is the classical view she criticised.</li><li>(B) Their names only — Categorisation is not based on names alone.</li><li>(D) Remembering every example we have ever seen equally — Storing every example equally is closer to exemplar theory.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Basic-level categories (e.g. ‘chair’) are learned first and used most.</li><li>Typical members are verified faster.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 66, "question": "Eric Kandel won the Nobel Prize (2000) largely for showing the cellular basis of learning, such as habituation and sensitisation, in the sea slug:", "options": ["Octopus", "Aplysia", "C. elegans", "Drosophila"], "correctAnswer": 1, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Kandel studied the gill-withdrawal reflex of Aplysia californica, showing that learning changes the strength of specific synapses and that long-term memory needs new protein synthesis.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Octopus — The octopus was not his model.</li><li>(C) C. elegans — C. elegans is a worm used in neural circuit studies.</li><li>(D) Drosophila — Drosophila (fruit fly) is used in genetics of learning.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Short-term memory involves changes in existing proteins; long-term needs gene expression (CREB).</li><li>Kandel wrote ‘In Search of Memory’ (2006).</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 67, "question": "In an experiment, the variable that the researcher deliberately manipulates is the:", "options": ["Independent variable", "Confounding variable", "Dependent variable", "Extraneous variable"], "correctAnswer": 0, "subject": "Research & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The independent variable is manipulated by the researcher; the dependent variable is measured to see its effect.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Confounding variable — A confounding variable varies with the IV and distorts results.</li><li>(C) Dependent variable — The dependent variable is measured, not manipulated.</li><li>(D) Extraneous variable — Extraneous variables are other influences to be controlled.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Operational definitions make variables measurable.</li><li>Random assignment controls many extraneous variables.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 68, "question": "Studies show that rat pups who receive little licking and grooming from their mothers have more methyl groups on the glucocorticoid receptor gene and become more stress-reactive. This is an example of:", "options": ["Imprinting", "A new genetic mutation", "Classical conditioning", "Epigenetic modification of gene expression"], "correctAnswer": 3, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Michael Meaney’s work showed that early care changes DNA methylation, altering gene expression without changing the DNA sequence — an epigenetic effect.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Imprinting — Imprinting is rapid early attachment learning in birds.</li><li>(B) A new genetic mutation — The DNA sequence itself is unchanged, so it is not a mutation.</li><li>(C) Classical conditioning — Classical conditioning is learned association.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Epigenetics helps explain gene–environment interaction.</li><li>Some epigenetic marks may pass across generations.</li></ul>", "examWatch": "A fresh, predicted question. The neighbouring topics are asked often, so it is worth knowing."}, {"id": 69, "question": "A client who believes ‘If I speak up in a meeting, everyone will laugh at me’ agrees to try speaking once at the next meeting and to note what actually happens. This CBT technique is a:", "options": ["Behavioural experiment", "Flooding", "Free association", "Empty-chair technique"], "correctAnswer": 0, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Behavioural experiments test the accuracy of a belief through planned action, collecting real evidence instead of only discussing it.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Flooding — Flooding is intense prolonged exposure to a feared stimulus.</li><li>(C) Free association — Free association is a psychoanalytic technique.</li><li>(D) Empty-chair technique — The empty chair is a Gestalt technique.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Behavioural experiments are central in Clark and Wells’s CBT for social anxiety.</li><li>They are often more powerful than verbal disputing.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 70, "question": "Giving a test with the same instructions, time limits and scoring rules to everyone is called:", "options": ["Norming", "Item analysis", "Standardisation of administration", "Validation"], "correctAnswer": 2, "subject": "Assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Standardised administration keeps testing conditions the same for everyone, so differences in scores reflect the people, not the procedure.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Norming — Norming collects reference scores from a sample.</li><li>(B) Item analysis — Item analysis evaluates individual items.</li><li>(D) Validation — Validation checks whether the test measures what it should.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Deviations from standard procedure make norms invalid.</li><li>A test manual specifies the standard procedure.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 71, "question": "<span class=\"pyq-badge\">PYQ</span>A researcher finds a correlation of r = -0.85 between stress and sleep quality. This indicates:", "options": ["A weak negative relationship", "A strong positive relationship", "A strong negative relationship", "No relationship"], "correctAnswer": 2, "subject": "Research & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> −0.85 is close to −1, so the relationship is strong; the minus sign means that as stress rises, sleep quality falls.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) A weak negative relationship — 0.85 is not weak.</li><li>(B) A strong positive relationship — The sign shows it is negative, not positive.</li><li>(D) No relationship — There is clearly a relationship.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The size shows strength; the sign shows direction.</li><li>Correlation does not prove causation.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 72, "question": "Mild neurocognitive disorder in DSM-5 differs from major neurocognitive disorder mainly because in the mild form:", "options": ["There is no cognitive decline at all", "Memory is always spared", "The cause is always vascular", "Cognitive decline does not interfere with independence in everyday activities"], "correctAnswer": 3, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In mild NCD, decline is modest and the person still manages everyday activities independently (perhaps with more effort). In major NCD (dementia), decline interferes with independence.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) There is no cognitive decline at all — Mild NCD does involve measurable decline.</li><li>(B) Memory is always spared — Memory may or may not be affected.</li><li>(C) The cause is always vascular — Mild NCD can have many causes.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Mild NCD is similar to ‘mild cognitive impairment’ (MCI).</li><li>Many people with MCI progress to dementia over the years.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 73, "question": "Frederic Bartlett, in ‘Remembering’ (1932), had English participants repeatedly recall a Native American folk tale, ‘The War of the Ghosts’. He found that recall was:", "options": ["Better for unfamiliar details than for familiar ones", "Reconstructed to fit their own cultural schemas, becoming shorter and more familiar", "Unaffected by the participants’ culture", "Almost perfectly accurate over time"], "correctAnswer": 1, "subject": "Cognition, learning & motivation", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Bartlett showed that memory is reconstructive: details were dropped, unfamiliar elements were changed to familiar ones (‘canoe’ became ‘boat’), and the story was rationalised.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Better for unfamiliar details than for familiar ones — Unfamiliar details were the ones most often changed or lost.</li><li>(C) Unaffected by the participants’ culture — Culture strongly shaped the changes.</li><li>(D) Almost perfectly accurate over time — Recall became distorted, not accurate.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Bartlett used the methods of repeated and serial reproduction.</li><li>Elizabeth Loftus’s misinformation studies also show reconstructive memory.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 74, "question": "A 16-year-old boy has repeated episodes, each lasting about a week, of sleeping up to 20 hours a day, eating excessively and behaving in a disinhibited way. Between episodes he is completely normal. This rare condition is:", "options": ["Prader–Willi syndrome", "Kleine–Levin syndrome", "Narcolepsy", "Bipolar disorder"], "correctAnswer": 1, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Kleine–Levin syndrome (recurrent hypersomnia) mainly affects adolescent boys: episodes of extreme sleepiness with cognitive and behavioural changes (hyperphagia, hypersexuality), with normal functioning between episodes.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Prader–Willi syndrome — Prader–Willi syndrome causes constant overeating from childhood.</li><li>(C) Narcolepsy — Narcolepsy causes daily sleepiness, cataplexy and sleep attacks, not week-long episodes.</li><li>(D) Bipolar disorder — Bipolar depression would show mood episodes, not this pattern.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>It usually resolves by adulthood.</li><li>DSM-5 lists recurrent hypersomnia under hypersomnolence disorder.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 75, "question": "Bibb Latané’s social impact theory proposes that the influence of others depends on their:", "options": ["Strength, immediacy and number", "Attractiveness alone", "Distance from home", "Age, gender and status only"], "correctAnswer": 0, "subject": "Social psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Latané (1981): social impact = f(strength × immediacy × number) of the sources. Each extra person adds less impact than the one before.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Attractiveness alone — Attractiveness is one possible source of strength.</li><li>(C) Distance from home — Distance from home is not part of the theory.</li><li>(D) Age, gender and status only — Age, gender and status are only parts of ‘strength’.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>It helps explain conformity, social loafing and bystander effects.</li><li>Dynamic social impact theory explains how cultures form.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 76, "question": "In Indian psychology based on Samkhya philosophy, the three gunas that make up human nature are:", "options": ["Atman, Brahman and maya", "Vata, pitta and kapha", "Dharma, artha and kama", "Sattva, rajas and tamas"], "correctAnswer": 3, "subject": "History, Indian psychology & ethics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The triguna theory says personality is a mix of sattva (purity, calm, knowledge), rajas (activity, passion) and tamas (inertia, dullness).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Atman, Brahman and maya — Atman, Brahman and maya are Vedantic concepts.</li><li>(B) Vata, pitta and kapha — Vata, pitta and kapha are Ayurvedic doshas.</li><li>(C) Dharma, artha and kama — Dharma, artha and kama are aims of life (purusharthas).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Indian scales such as the Vedic Personality Inventory measure the gunas.</li><li>The Bhagavad Gita describes the gunas in detail.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 77, "question": "According to Daniel Batson’s empathy–altruism hypothesis, people feeling strong empathy for someone in need will help:", "options": ["Only when they will be rewarded", "Only when others are watching", "Even when it is easy to escape without helping, out of genuine concern", "Only to reduce their own distress"], "correctAnswer": 2, "subject": "Social psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Batson found that high-empathy participants helped even when escape was easy, suggesting a truly altruistic motive, not just relief of their own discomfort.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Only when they will be rewarded — Reward-seeking is the social exchange view.</li><li>(B) Only when others are watching — Audience effects are a separate factor.</li><li>(D) Only to reduce their own distress — Reducing one’s own distress is the egoistic (negative-state relief) view.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cialdini argued for the negative-state relief model.</li><li>Kin selection explains helping relatives.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 78, "question": "In a 2 × 2 study, a new therapy reduces anxiety in women but not in men. This pattern is best described as:", "options": ["An interaction effect between therapy and gender", "No effect", "A main effect of gender only", "A main effect of therapy only"], "correctAnswer": 0, "subject": "Research & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> An interaction occurs when the effect of one IV (therapy) depends on the level of another IV (gender). Non-parallel lines on a graph show it.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) No effect — There is clearly an effect in women.</li><li>(C) A main effect of gender only — A main effect of gender alone would not depend on therapy.</li><li>(D) A main effect of therapy only — A therapy main effect would apply to both genders.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Factorial designs test main effects and interactions together.</li><li>Interpret main effects with caution when an interaction exists.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 79, "question": "Jerome Kagan described some infants as ‘behaviourally inhibited’. Such children are most likely to:", "options": ["Be fearless and highly sociable", "Show intellectual disability", "Have an insecure–avoidant attachment in all cases", "Be shy and cautious with unfamiliar people and situations"], "correctAnswer": 3, "subject": "Development", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Kagan found that about 15–20% of infants are highly reactive and later shy and cautious in novel situations, a temperament linked with later social anxiety.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Be fearless and highly sociable — Fearless sociability is the uninhibited profile.</li><li>(B) Show intellectual disability — Temperament is not linked with intellectual disability.</li><li>(C) Have an insecure–avoidant attachment in all cases — Temperament does not determine attachment type.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>High reactivity is linked with amygdala responsiveness.</li><li>Many inhibited children become less shy with supportive parenting.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 80, "question": "<span class=\"pyq-badge\">PYQ</span>In signal detection theory, the ability to distinguish a stimulus from background noise is:", "options": ["Sensitivity (d′)", "Criterion (β)", "ROC curve", "JND"], "correctAnswer": 0, "subject": "Cognition, learning & motivation", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> d′ (d-prime) measures how well a signal can be separated from noise. β is the response criterion — how willing the observer is to say ‘yes’.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Criterion (β) — The criterion reflects bias, not sensitivity.</li><li>(C) ROC curve — An ROC curve plots hits against false alarms.</li><li>(D) JND — The JND is a difference threshold from classical psychophysics.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Outcomes: hit, miss, false alarm, correct rejection.</li><li>Green and Swets (1966) applied SDT to psychophysics.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 81, "question": "J.B.P. Sinha proposed a leadership style suited to Indian organisations, in which the leader is caring but also firmly task-focused. It is called:", "options": ["Charismatic leader", "Nurturant-task leader", "Laissez-faire leader", "Transformational leader"], "correctAnswer": 1, "subject": "History, Indian psychology & ethics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Jai B.P. Sinha (1980) described the nurturant-task (NT) leader, combining warmth and personal care with an emphasis on getting work done — fitting Indian cultural expectations.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Charismatic leader — Charismatic leadership was described by Weber and House.</li><li>(C) Laissez-faire leader — Laissez-faire is a hands-off style (Lewin).</li><li>(D) Transformational leader — Transformational leadership was described by Burns and Bass.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Durganand Sinha worked on indigenisation of psychology in India.</li><li>The NT leader can become participative as subordinates mature.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 82, "question": "Neo-Piagetian theorists such as Juan Pascual-Leone and Robbie Case explained stage changes mainly through increases in:", "options": ["Physical growth", "Moral reasoning", "Social interaction with peers", "Working memory capacity (mental or executive processing space)"], "correctAnswer": 3, "subject": "Development", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Neo-Piagetians kept stages but explained them with information processing: as working memory (Pascual-Leone’s ‘M-space’; Case’s executive processing space) grows, children handle more complex thinking.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Physical growth — Physical growth is not the explanation.</li><li>(B) Moral reasoning — Moral reasoning is Kohlberg’s area.</li><li>(C) Social interaction with peers — Social interaction is Vygotsky’s focus.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Case described ‘central conceptual structures’.</li><li>Fischer’s skill theory is another neo-Piagetian approach.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 83, "question": "Tele-MANAS, India’s national tele-mental health programme launched in 2022, can be reached on the toll-free number:", "options": ["14416", "108", "112", "1098"], "correctAnswer": 0, "subject": "History, Indian psychology & ethics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Tele-MANAS (Tele Mental Health Assistance and Networking Across States) was launched in October 2022 and offers 24×7 free counselling on 14416 (or 1-800-891-4416).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 108 — 108 is the emergency ambulance number.</li><li>(C) 112 — 112 is the national emergency number.</li><li>(D) 1098 — 1098 is Childline.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>NIMHANS is the nodal centre for Tele-MANAS.</li><li>It provides counselling in many Indian languages.</li></ul>", "examWatch": "This angle is new, but the topic around it is popular with examiners — don’t skip it."}, {"id": 84, "question": "A researcher deliberately selects only experienced clinical psychologists who have treated at least 50 patients with OCD, to interview about ERP. This sampling method is:", "options": ["Systematic sampling", "Purposive sampling", "Simple random sampling", "Stratified sampling"], "correctAnswer": 1, "subject": "Research & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Purposive (judgemental) sampling chooses people with specific characteristics relevant to the study. It is common in qualitative research.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Systematic sampling — Systematic sampling picks every kth person.</li><li>(C) Simple random sampling — Simple random sampling gives everyone an equal chance.</li><li>(D) Stratified sampling — Stratified sampling divides the population into strata first.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Purposive sampling is non-probability sampling.</li><li>Theoretical sampling in grounded theory is a type of purposive sampling.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 85, "question": "The first social psychology experiment is often said to be Norman Triplett’s 1898 study, which found that:", "options": ["Groups make riskier decisions than individuals", "People obey authority to harm others", "Cyclists rode faster when racing against others than when riding alone", "People conform to group judgements of line length"], "correctAnswer": 2, "subject": "Social psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Triplett noticed cyclists were faster with competitors and showed that children wound fishing reels faster in pairs — early evidence of social facilitation.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Groups make riskier decisions than individuals — Riskier group decisions were Stoner’s ‘risky shift’.</li><li>(B) People obey authority to harm others — Obedience was Milgram’s work.</li><li>(D) People conform to group judgements of line length — Line judgements were Asch’s studies.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Zajonc (1965) explained social facilitation by arousal.</li><li>Allport coined the term ‘social facilitation’ (1924).</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 86, "question": "In Piaget’s ‘three mountains’ task, a preoperational child describes the doll’s view as identical to his own. This shows:", "options": ["Object permanence", "Conservation", "Egocentrism", "Hypothetico-deductive reasoning"], "correctAnswer": 2, "subject": "Development", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Piaget and Inhelder (1956) used the three mountains task to show egocentrism — difficulty taking another person’s visual perspective.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Object permanence — Object permanence develops in infancy.</li><li>(B) Conservation — Conservation is about quantity staying the same.</li><li>(D) Hypothetico-deductive reasoning — Hypothetico-deductive reasoning belongs to formal operations.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Hughes’ ‘policeman’ task showed children can take perspectives earlier in familiar tasks.</li><li>Egocentrism declines in the concrete operational stage.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 87, "question": "The term ‘emotional intelligence’ was first defined as a formal concept in 1990 by:", "options": ["Daniel Goleman", "Peter Salovey and John Mayer", "Robert Sternberg", "Howard Gardner"], "correctAnswer": 1, "subject": "Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Salovey and Mayer (1990) defined emotional intelligence as the ability to perceive, understand, use and manage emotions. Goleman popularised it in 1995.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Daniel Goleman — Goleman popularised it but did not first define it.</li><li>(C) Robert Sternberg — Sternberg proposed the triarchic theory.</li><li>(D) Howard Gardner — Gardner proposed multiple intelligences, including intrapersonal and interpersonal.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The MSCEIT measures EI as an ability.</li><li>Bar-On’s EQ-i is a self-report measure.</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 88, "question": "The famous debate on whether emotional reactions can occur before any cognitive appraisal was between:", "options": ["Paul Ekman and Carroll Izard", "Stanley Schachter and Jerome Singer", "William James and Walter Cannon", "Robert Zajonc and Richard Lazarus"], "correctAnswer": 3, "subject": "Cognition, learning & motivation", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Zajonc (1980, ‘Preferences need no inferences’) argued that affect can come first; Lazarus (1982, 1984) argued that cognitive appraisal is always needed for emotion.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Paul Ekman and Carroll Izard — Ekman and Izard both studied basic emotions.</li><li>(B) Stanley Schachter and Jerome Singer — Schachter and Singer worked together on the two-factor theory.</li><li>(C) William James and Walter Cannon — James and Cannon debated whether bodily changes come before emotion.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Zajonc’s mere exposure findings supported his view.</li><li>LeDoux’s ‘low road’ to the amygdala gives neural support to fast affect.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 89, "question": "Robert Sternberg’s triangular theory of love includes all of the following components, EXCEPT:", "options": ["Commitment", "Loyalty", "Passion", "Intimacy"], "correctAnswer": 1, "subject": "Social psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Sternberg (1986) proposed three components — intimacy, passion and commitment. All three together make ‘consummate love’.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Commitment — Commitment is a component.</li><li>(C) Passion — Passion is a component.</li><li>(D) Intimacy — Intimacy is a component.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Intimacy + passion = romantic love; intimacy + commitment = companionate love.</li><li>Hazan and Shaver linked adult love to attachment styles.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 90, "question": "Functional MRI usually measures the BOLD signal, which reflects:", "options": ["Changes in blood oxygenation linked with neural activity", "The density of grey matter", "Direct electrical firing of single neurons", "Glucose metabolism measured with a radioactive tracer"], "correctAnswer": 0, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> BOLD (blood-oxygen-level-dependent) contrast detects changes in oxygenated versus deoxygenated haemoglobin as active brain areas receive more blood.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) The density of grey matter — Grey-matter density is measured with structural MRI.</li><li>(C) Direct electrical firing of single neurons — Electrical activity is measured by EEG or single-cell recording.</li><li>(D) Glucose metabolism measured with a radioactive tracer — Radioactive glucose tracers are used in PET.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Seiji Ogawa described BOLD contrast (1990).</li><li>fMRI has good spatial but limited temporal resolution.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 91, "question": "A new anxiety questionnaire improves the prediction of treatment dropout beyond what an existing interview already predicts. This added predictive power is called:", "options": ["Test–retest reliability", "Content validity", "Incremental validity", "Face validity"], "correctAnswer": 2, "subject": "Assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Incremental validity is the extra prediction a measure adds over existing measures (often tested with hierarchical regression).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Test–retest reliability — Test–retest reliability is stability over time.</li><li>(B) Content validity — Content validity is about covering the domain.</li><li>(D) Face validity — Face validity is about appearance.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Sechrest (1963) stressed incremental validity.</li><li>It helps decide whether a test is worth the time it takes.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 92, "question": "All of the following are factors in the HEXACO model of personality, EXCEPT:", "options": ["Emotionality", "Honesty–Humility", "Conscientiousness", "Psychoticism"], "correctAnswer": 3, "subject": "Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> HEXACO (Ashton and Lee): Honesty–Humility, Emotionality, eXtraversion, Agreeableness, Conscientiousness and Openness. Psychoticism belongs to Eysenck’s PEN model.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Emotionality — Emotionality is a HEXACO factor.</li><li>(B) Honesty–Humility — Honesty–Humility is the sixth factor HEXACO adds.</li><li>(C) Conscientiousness — Conscientiousness is a HEXACO factor.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Low Honesty–Humility is linked with the dark traits.</li><li>HEXACO came from lexical studies in several languages.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 93, "question": "In psychoanalytic therapy, a client who keeps ‘forgetting’ sessions and changes the subject whenever painful memories come up is showing:", "options": ["Sublimation", "Resistance", "Abreaction", "Transference"], "correctAnswer": 1, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Resistance is the unconscious opposition to bringing painful material into awareness. Interpreting it is a key part of analysis.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Sublimation — Sublimation is a mature defence that channels impulses.</li><li>(C) Abreaction — Abreaction is emotional release when a memory is recalled.</li><li>(D) Transference — Transference is directing feelings about past figures onto the therapist.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Forms of resistance: silence, lateness, intellectualising.</li><li>Freud saw resistance as protecting against anxiety.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 94, "question": "Albert Bandura’s idea that behaviour, personal factors and the environment all influence one another is called:", "options": ["Behavioural genetics", "Vicarious reinforcement", "Reciprocal determinism", "Self-efficacy"], "correctAnswer": 2, "subject": "Personality", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Reciprocal (triadic) determinism means personal factors (cognitions), behaviour and the environment interact and shape each other.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Behavioural genetics — Behavioural genetics studies genetic influences.</li><li>(B) Vicarious reinforcement — Vicarious reinforcement is learning from others’ rewards.</li><li>(D) Self-efficacy — Self-efficacy is belief in one’s ability to succeed.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Bandura called his later approach social cognitive theory (1986).</li><li>It rejects one-way environmental determinism.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 95, "question": "In DSM-5, agoraphobia requires marked fear or anxiety about at least how many of these five situations: public transport, open spaces, enclosed places, queues or crowds, and being outside the home alone?", "options": ["Two", "One", "Three", "All five"], "correctAnswer": 0, "subject": "Psychopathology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> DSM-5 agoraphobia needs fear or avoidance in at least two of the five situation groups, because escape might be difficult or help unavailable.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) One — One situation suggests a specific phobia.</li><li>(C) Three — Three is not the rule.</li><li>(D) All five — All five are not required.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DSM-5 made agoraphobia a separate diagnosis from panic disorder.</li><li>Duration: typically 6 months or more.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 96, "question": "The Woodcock–Johnson tests (WJ-IV) are built mainly on which model of intelligence?", "options": ["Gardner’s multiple intelligences", "Sternberg’s triarchic theory", "Spearman’s two-factor theory only", "Cattell–Horn–Carroll (CHC) theory"], "correctAnswer": 3, "subject": "Assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The WJ tests are the most closely CHC-based battery, measuring broad abilities such as fluid reasoning, comprehension-knowledge, processing speed and long-term retrieval.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Gardner’s multiple intelligences — Gardner’s theory has no major standard test battery.</li><li>(B) Sternberg’s triarchic theory — Sternberg’s theory is not the basis.</li><li>(C) Spearman’s two-factor theory only — CHC includes g but is much broader than Spearman.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Carroll’s three-stratum theory (1993) was combined with Cattell–Horn Gf-Gc.</li><li>CHC also guides cross-battery assessment.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 97, "question": "Donald Hebb’s (1949) rule, often summarised as ‘cells that fire together wire together’, proposes that:", "options": ["Memories are stored in single neurons", "New neurons are formed whenever we learn", "Neurons die if they are not used", "Repeated joint activity strengthens the synaptic connection between two neurons"], "correctAnswer": 3, "subject": "Biological & neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Hebb proposed that when one neuron repeatedly helps fire another, the connection grows stronger, forming ‘cell assemblies’. Long-term potentiation is the cellular evidence.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Memories are stored in single neurons — Hebb saw memories as stored in assemblies of cells, not single cells.</li><li>(B) New neurons are formed whenever we learn — Hebb’s rule is about synapses, not new neurons.</li><li>(C) Neurons die if they are not used — Pruning of unused connections is a different process.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Hebb’s book: The Organization of Behavior (1949).</li><li>Hebb also studied enriched environments in rats.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 98, "question": "To assess the agreement among three or more judges who each rank the same set of items, the appropriate statistic is:", "options": ["Point-biserial correlation", "Kendall’s coefficient of concordance (W)", "Pearson’s r", "Cohen’s d"], "correctAnswer": 1, "subject": "Research & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Kendall’s W (0 to 1) measures agreement among several judges’ rankings.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Point-biserial correlation — Point-biserial relates a continuous and a dichotomous variable.</li><li>(C) Pearson’s r — Pearson’s r correlates two continuous variables.</li><li>(D) Cohen’s d — Cohen’s d is an effect size for mean differences.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Spearman’s rho correlates two sets of ranks.</li><li>Cohen’s kappa is for two raters with categories.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 99, "question": "Harry Harlow found that infant monkeys spent most of their time clinging to a soft cloth ‘mother’ rather than a wire ‘mother’ that gave milk. This showed the importance of:", "options": ["Imprinting in primates", "Feeding in attachment", "Contact comfort in attachment", "Reinforcement by food"], "correctAnswer": 2, "subject": "Development", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Harlow (1958) showed that attachment depends on contact comfort, not just on feeding — challenging ‘cupboard love’ theories.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Imprinting in primates — Imprinting is rapid bonding in birds.</li><li>(B) Feeding in attachment — Feeding alone did not create attachment.</li><li>(D) Reinforcement by food — Food reinforcement did not explain the preference.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Isolated monkeys later showed severe social problems.</li><li>Harlow’s work influenced Bowlby’s attachment theory.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 100, "question": "To treat panic disorder, a therapist asks the client to spin in a chair and breathe through a narrow straw to bring on dizziness and breathlessness, until these sensations no longer cause fear. This is:", "options": ["Interoceptive exposure", "In vivo exposure to places", "Aversion therapy", "Systematic desensitisation with relaxation"], "correctAnswer": 0, "subject": "Therapies", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Interoceptive exposure deliberately brings on feared bodily sensations so that the client learns they are harmless. It is a core part of CBT for panic (Barlow’s Panic Control Treatment).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) In vivo exposure to places — In vivo exposure targets external feared places or situations.</li><li>(C) Aversion therapy — Aversion therapy pairs a behaviour with unpleasant stimuli.</li><li>(D) Systematic desensitisation with relaxation — Systematic desensitisation uses relaxation and imagined hierarchy items.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Clark’s model: catastrophic misinterpretation of bodily sensations.</li><li>Hyperventilation and stair-climbing are other interoceptive exercises.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}];
